BEGIN{IGNORECASE=1}
{ 
  if ($0 ~ /^ERROR:/) {inblock=1; msg=substr($0, index($0, ":")+1); next}
  if (inblock && $0 ~ /^[ 	]+/) {msg = msg" "$0; next}
  if (inblock && $0 !~ /^[ 	]/) {inblock=0; 
    ts=extract_ts(prev); key=tolower(norm(msg)); count[key]++
  }
  if ($0 ~ /^\d{4}-\d{2}-\d{2}/) {prev=$0}
}
END{for (k in count) print k, count[k]}
